do $constraint$declare prior text;begin
 select pg_get_constraintdef(oid)into strict prior from pg_constraint where conrelid='public.matches'::regclass and conname='paired_result_availability'and convalidated;
 perform private_fcf_six_target_release.require(left(prior,6)='CHECK 'and right(prior,1)=')'and position('private_fcf_g1_supplement.unknown_result_allowed'in prior)>0 and position('private_fcf_six_history.unknown_result_allowed'in prior)>0 and position('private_baden_history.unknown_result_allowed'in prior)>0 and position('private_fcf_g1_9410'in prior)=0,'complete installed pure NULL-result CHECK required');
