 if tg_op<>'DELETE'and new.zapisnik_id='es4109410'and new.statistics_status='unavailable_historical'then
  if private_fcf_g1_9410.exact_match(new)is not true or exists(select 1 from appearances where match_id=new.id)or exists(select 1 from goals where match_id=new.id)then raise exception 'FCF_G1_9410: exact empty installed native marker required';end if;return new;
