 definition:=pg_get_functiondef('private_historical_statistics.protect_match()'::regprocedure);execute replace(definition,body,patched);
end$protect$;

create function private_fcf_g1_9410.individual_guard()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin
 if exists(select 1 from private_fcf_g1_9410.markers where match_id=new.match_id)then raise exception 'FCF_G1_9410: individual statistics unavailable';end if;return new;
