create function private_fcf_g1_9410.install409(v jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s jsonb:=v->'supplementalBinding';m public.matches%rowtype;before_text text;before_sha text;after_image jsonb;projection jsonb;protected_six jsonb;begin
 perform private_fcf_g1_scores.assert_supplement_scores(v->'derivedScoresBefore');
 if exists(select 1 from private_fcf_g1_supplement.markers)then perform private_fcf_g1_supplement.readback(s);return;end if;
 -- Caller already holds lock_target and the complete dependency locks. Recheck
 -- actual persisted native IDs; this path never resolves a title/name to an ID.
 select *into m from matches where id=(s#>>'{native,matchId}')::bigint for update;
 perform private_fcf_six_target_release.require(m.id is not null and((not(s ? 'prelaunch')and m.zapisnik_id='es4109409'and not m.vir_brez_izida)or(s ? 'prelaunch'and private_fcf_g1_supplement.legacy_placeholder(m)and to_jsonb(m)=(s#>>'{prelaunch,beforeImageText}')::jsonb))and m.round_id=(s#>>'{native,roundId}')::bigint and m.home_team_id=(s#>>'{native,homeTeamId}')::bigint and m.away_team_id=(s#>>'{native,awayTeamId}')::bigint and m.played_on='2026-10-04'and m.imported_at is null and m.statistics_status='available'and not m.kontumacija and cardinality(m.import_warnings)=0 and m.source_phase is null and(m.source_round is null or m.source_round=3)and not exists(select 1 from appearances where match_id=m.id)and not exists(select 1 from goals where match_id=m.id),'exact empty unimported native supplement; populated/guessed/dependent state HOLD');
 perform private_fcf_six_target_release.require(exists(select 1 from rounds r join competitions c on c.id=r.competition_id where r.id=m.round_id and r.competition_id=783 and r.season='2026/27'and r.number=3 and not c.active)and not exists(select 1 from matches where zapisnik_id='es4109409'and id<>m.id)and(select count(*)from matches where round_id=m.round_id and home_team_id=m.home_team_id and away_team_id=m.away_team_id and played_on=m.played_on)=1,'inactive unique actual native placeholder/calendar/report collision');
 perform private_fcf_six_target_release.no_target_users(783);
 projection:=private_fcf_g1_readonly.capture('es-ct-segona-g1',array[]::text[]);
 perform private_fcf_six_target_release.require(not(s ? 'prelaunch')or exists(select 1 from jsonb_array_elements(projection#>'{native,dependencies,rounds}')d where(d->>'roundId')::bigint=m.round_id and d->>'lineupRows'='0'and d->>'rosterRows'='0'and d->>'transferRows'='0'and d->>'chipRows'='0'),'zero human legacy placeholder round dependencies; derived scores reverified separately');
 perform private_fcf_six_target_release.require(projection#>>'{native,dependencies,complete}'='true'and projection#>>'{native,dependencies,competitionUserRows}'='0'and exists(select 1 from jsonb_array_elements(projection#>'{native,dependencies,matches}')d where(d->>'matchId')::bigint=m.id and d->>'appearances'='0'and d->>'goals'='0'),'complete locked zero individual/card/user supplement dependencies');
 select jsonb_build_object('cleanup',(select to_jsonb(c)from private_fcf_future_history.cleanup_receipt c where singleton),'six',(select jsonb_agg(public.get_installed_historical_statistics_markers(id)order by id)from competitions where id in(783,790,797)))into protected_six;
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_each((projection->>'dependencySnapshotText')::jsonb->'relations')q where q.value->>'globalUser'='true'and(q.value->>'count')::bigint<>0),'zero actual human dependency relations');
 before_text:=jsonb_build_object('match',to_jsonb(m),'appearances','[]'::jsonb,'goals','[]'::jsonb,'dependencySnapshotText',projection->>'dependencySnapshotText','dependencySnapshotSha256',projection->>'dependencySnapshotSha256')::text;before_sha:=encode(sha256(convert_to(before_text,'UTF8')),'hex');
 insert into private_fcf_g1_supplement.markers(match_id,round_id,home_team_id,away_team_id,binding,before_image_text,before_sha256,authorized_xid)values(m.id,m.round_id,m.home_team_id,m.away_team_id,s,before_text,before_sha,txid_current());
