create function private_fcf_g1_9410.install(v jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s jsonb:=v->'supplement4109410Binding';m public.matches%rowtype;before_text text;before_sha text;after_image jsonb;projection jsonb;protected_six jsonb;begin
 perform private_fcf_g1_scores.assert_supplement_scores(v->'derivedScoresBefore');
