 -- Caller already holds lock_target and the complete dependency locks. Recheck
 -- actual persisted native IDs; this path never resolves a title/name to an ID.
 select *into m from matches where id=(s#>>'{native,matchId}')::bigint for update;
 perform private_fcf_six_target_release.require(m.id is not null and((not(s ? 'prelaunch')and m.zapisnik_id='es4109410'and not m.vir_brez_izida)or(s ? 'prelaunch'and private_fcf_g1_9410.legacy_placeholder(m)and to_jsonb(m)=(s#>>'{prelaunch,beforeImageText}')::jsonb))and m.round_id=(s#>>'{native,roundId}')::bigint and m.home_team_id=(s#>>'{native,homeTeamId}')::bigint and m.away_team_id=(s#>>'{native,awayTeamId}')::bigint and m.played_on='2026-10-04'and m.imported_at is null and m.statistics_status='available'and not m.kontumacija and cardinality(m.import_warnings)=0 and m.source_phase is null and(m.source_round is null or m.source_round=3)and not exists(select 1 from appearances where match_id=m.id)and not exists(select 1 from goals where match_id=m.id),'exact empty unimported native supplement; populated/guessed/dependent state HOLD');
 perform private_fcf_six_target_release.require(exists(select 1 from rounds r join competitions c on c.id=r.competition_id where r.id=m.round_id and r.competition_id=783 and r.season='2026/27'and r.number=3 and not c.active)and not exists(select 1 from matches where zapisnik_id='es4109410'and id<>m.id)and(select count(*)from matches where round_id=m.round_id and home_team_id=m.home_team_id and away_team_id=m.away_team_id and played_on=m.played_on)=1,'inactive unique actual native placeholder/calendar/report collision');
