 update matches set zapisnik_id='es4109410',vir_brez_izida=false,home_goals=null,away_goals=null,imported_at=null,statistics_status='unavailable_historical',statistics_reason='closed_official_result_and_individual_statistics_unavailable',source_url='https://www.fcf.cat/ca/competicio/acta/4109410',source_phase=null,source_round=3 where id=m.id;
